import{Utils}from"../utils.min.js?v=1.0.0";import Global_Base_Component from"../component/global-base-component.min.js?v=1.0.0";let __=wp.i18n.__,Feature_Base_Component={extends:Global_Base_Component,props:{featureData:{default:null},tierIndex:{default:1,type:Number},additionalTier:{type:Boolean,default:!1},deleteWarning:{type:String,default:__("Do you want to delete this tier?","shipflex")}},emits:["update","duplicate","delete"],data(){return{collapse:!1,condition_groups:[],id:Utils.generate_uuid()}},computed:{tier_no(){return this.tierIndex+1},feature_data(){return JSON.parse(JSON.stringify(this.$data))},calculation_metrics(){return shipflex_admin.calculation_metrics}},watch:{feature_data:{deep:!0,handler(e){this.$emit("update",e)}}},mounted(){},updated(){},methods:{duplicate_tier(){this.$emit("duplicate",{...this.feature_data,id:Utils.generate_uuid(),collapse:!1},this.tier_no)},delete_tier(){confirm(this.deleteWarning)&&this.$emit("delete")}}};export default Feature_Base_Component;